sys_ws_operation.operation_script:
(function process(request, response) {

    try {

        var managerId =
            gs.getUserID();


        // =====================================================
        // VERIFY MANAGER ROLE
        // =====================================================
        if (
            !gs.hasRole(
                'x_1760545_smarta_0.smartattend_manager'
            )
        ) {

            response.setStatus(403);

            response.setBody({
                success: false,
                message: 'Manager access is required.'
            });

            return;
        }


        // =====================================================
        // GET ACTIVE SHIFTS
        // =====================================================
        var shifts = [];


        var shiftGR =
            new GlideRecord(
                'x_1760545_smarta_0_shift'
            );


        shiftGR.addQuery(
            'active',
            true
        );


        shiftGR.orderBy(
            'start_minutes'
        );


        shiftGR.query();


        while (
            shiftGR.next()
        ) {

            var startMinutes =
                parseInt(
                    shiftGR.getValue(
                        'start_minutes'
                    ) || 0,
                    10
                );


            var endMinutes =
                parseInt(
                    shiftGR.getValue(
                        'end_minutes'
                    ) || 0,
                    10
                );


            shifts.push({

                shift_id:
                    shiftGR.getUniqueValue(),

                number:
                    shiftGR.getValue(
                        'number'
                    ) || '',

                shift_name:
                    shiftGR.getValue(
                        'shift_name'
                    ) ||
                    shiftGR.getDisplayValue(),

                start_minutes:
                    startMinutes,

                end_minutes:
                    endMinutes,

                start_time:
                    minutesToTime(
                        startMinutes
                    ),

                end_time:
                    minutesToTime(
                        endMinutes
                    ),

                grace_minutes:
                    parseInt(
                        shiftGR.getValue(
                            'grace_minutes'
                        ) || 0,
                        10
                    ),

                full_day_minutes:
                    parseInt(
                        shiftGR.getValue(
                            'full_day_minutes'
                        ) || 0,
                        10
                    ),

                half_day_minutes:
                    parseInt(
                        shiftGR.getValue(
                            'half_day_minutes'
                        ) || 0,
                        10
                    ),

                description:
                    shiftGR.getValue(
                        'description'
                    ) || '',

                active:
                    shiftGR.getValue(
                        'active'
                    ) === '1'

            });

        }


        // =====================================================
        // GET EMPLOYEES UNDER LOGGED-IN MANAGER
        // =====================================================
        var employees = [];


        var profileGR =
            new GlideRecord(
                'x_1760545_smarta_0_employee_profile'
            );


        profileGR.addQuery(
            'manager',
            managerId
        );


        profileGR.addQuery(
            'active',
            true
        );


        profileGR.orderBy(
            'employee'
        );


        profileGR.query();


        while (
            profileGR.next()
        ) {

            var currentShiftId =
                profileGR.getValue(
                    'shift'
                ) || '';


            var currentShiftName =
                'Not Assigned';


            if (
                currentShiftId
            ) {

                currentShiftName =
                    profileGR.shift
                        .getDisplayValue() ||
                    'Not Assigned';

            }


            employees.push({

                profile_id:
                    profileGR.getUniqueValue(),

                employee_id:
                    profileGR.getValue(
                        'employee'
                    ),

                employee:
                    profileGR.employee
                        .getDisplayValue(),

                employee_code:
                    profileGR.getValue(
                        'employee_code'
                    ) || '',

                department:
                    profileGR.getValue(
                        'department'
                    ) || '',

                current_shift_id:
                    currentShiftId,

                current_shift:
                    currentShiftName,

                active:
                    profileGR.getValue(
                        'active'
                    ) === '1'

            });

        }


        // =====================================================
        // RESPONSE
        // =====================================================
        response.setStatus(200);

        response.setBody({

            success: true,

            manager:
                gs.getUserDisplayName(),

            shift_count:
                shifts.length,

            employee_count:
                employees.length,

            shifts:
                shifts,

            employees:
                employees

        });


        // =====================================================
        // HELPER
        // 540 -> 9:00 AM
        // =====================================================
        function minutesToTime(
            totalMinutes
        ) {

            totalMinutes =
                parseInt(
                    totalMinutes || 0,
                    10
                );


            var hour =
                Math.floor(
                    totalMinutes / 60
                );


            var minute =
                totalMinutes % 60;


            var suffix =
                hour >= 12
                    ? 'PM'
                    : 'AM';


            var displayHour =
                hour % 12;


            if (
                displayHour === 0
            ) {

                displayHour = 12;

            }


            var displayMinute =
                minute < 10
                    ? '0' + minute
                    : String(minute);


            return (
                displayHour +
                ':' +
                displayMinute +
                ' ' +
                suffix
            );

        }


    }
    catch (e) {

        gs.error(
            '[SmartAttend Shift Management] ' +
            e.message
        );


        response.setStatus(500);

        response.setBody({

            success: false,

            message:
                'Unable to load shift management data.'

        });

    }

})(request, response);
